import json, os
from datetime import datetime
from pathlib import Path

proj_dir = Path(os.environ.get('CLAUDE_PROJECT_DIR', '.')) / 'projects'
idx_file = proj_dir / '.index.json'
if idx_file.exists():
    idx = json.loads(idx_file.read_text())
    today = datetime.now()
    alerts = []
    for name, p in idx.get('projects', {}).items():
        target = p.get('target_date', '')
        if target:
            try:
                dt = datetime.strptime(target, '%Y-%m-%d')
                days_left = (dt - today).days
                if days_left < 0:
                    alerts.append(f'{name}: 已超期{-days_left}天')
                elif days_left < 3:
                    alerts.append(f'{name}: 仅剩{days_left}天')
            except:
                pass
    if alerts:
        print('⚠️  Deadline Alerts:')
        for a in alerts:
            print(f'  - {a}')
    else:
        print('✓ No deadline alerts')
"
